mapper.select:
SELECT AM.*, ( SELECT SE.AVATAR FROM SYS_EXTENSION SE WHERE SE.ENV_CODE = AM.ENV_CODE AND (SE.DELETED = 0 OR SE.DELETED IS NULL) AND AM.EXTENSION_CODE IS NOT NULL AND AM.EXTENSION_CODE != '' AND (SE.EXTENSION_CODE = AM.EXTENSION_CODE OR SE.EXTENSION_KEY = AM.EXTENSION_CODE) ORDER BY CASE WHEN SE.EXTENSION_CODE = AM.EXTENSION_CODE THEN 0 ELSE 1 END LIMIT 1 ) AS providerAvatar FROM `AI_MODEL` AM WHERE 1=1
AND AM.ENV_CODE = #{req.envCode}
AND AM.EXTENSION_CODE = #{req.extensionCode}
AND AM.MODEL_NAME LIKE CONCAT('%', #{req.modelName}, '%')
AND AM.MODEL_KEY = #{req.modelKey}
AND AM.ACCOUNT_KEY = #{req.accountKey}
AND AM.STATUS = #{req.status}
ORDER BY AM.EXTENSION_CODE DESC, AM.MODEL_TYPE DESC
